function signalFor(s,d){if(s.sports&&!s.sports.includes(state.sport))return'grey';if(s.type==='river'&&s.gaugeValidated!==true)return'grey';let n=windFit(d.wind).n,a=relation(d.dir,s.sea);if(a==='Offshore')n+=state.sport==='sup'||state.sport==='kite'?5:state.skill==='advanced'?0:2;else if(a==='Cross-offshore')n+=state.sport==='kite'?4:state.sport==='sup'?3:0;if(d.gust-d.wind>=8)n+=2;return n>=4?'red':n>=2?'amber':'green'}
function markerIcon(colour){return L.divIcon({className:'',html:`<div class="spot-marker ${colour}"><span></span></div>`,iconSize:[27,27],iconAnchor:[13,27]})}
function mapCard(id,colour){let s=spots[id],listed=!s.sports||s.sports.includes(state.sport),trip=s.trips?.[state.skill]||s.trips?.intermediate||s.trips?.beginner,patrol=rnliPatrolState(s,state.selectedTime?new Date(state.selectedTime):new Date());$('#mapType').textContent=((s.region?`${s.region} · `:'')+`${s.type} launch`).toUpperCase();$('#mapSpotName').textContent=s.name;$('#mapSignal').textContent=!listed?`${sports[state.sport]} not yet verified here`:colour==='grey'?'Loading forecast signal':colour==='green'?'Good for this profile':colour==='amber'?'Use extra caution':'Avoid for this profile';$('#mapSignalDot').className=colour;$('#mapAccess').textContent=s.access;$('#localIntel').innerHTML=`<span>LAUNCH-SIDE INTELLIGENCE</span><strong>${s.sea==null?'Inspect the exact get-in':`Open water: ${compass(s.sea)}`}</strong><small>${s.intel||'Zoom in and switch map layers to inspect roads, parking, shelter and the shoreline. Aerial imagery may be old; verify on arrival.'}</small>`;$('#sessionIdea').innerHTML=trip?`<span>${state.skill==='advanced'?'WEEKEND-WARRIOR MISSION':'SESSION IDEA'}</span><strong>${trip.title}</strong><small>${trip.detail}</small>`:`<span>SESSION IDEA</span><strong>${state.skill==='advanced'?'Search the nearby evidence pins':'Stay close to this launch'}</strong><small>${state.skill==='advanced'?'Switch sports and compare coast angles; only documented uses are surfaced.':'No documented route is loaded here yet. Do not invent a crossing from the shape of the map.'}</small>`;$('#rnliStatus').textContent=s.rnli?patrol.label:'No RNLI patrol data verified';$('#rnliDates').textContent=s.rnli?.dates||'This does not mean there is no local lifeguard service. Check live flags and the RNLI directory.';$('#rnliLink').href=s.rnli?.url||'https://rnli.org/find-my-nearest/lifeguarded-beaches'}
function chooseFromMap(id){if(!spots[id])return;state.spot=id;document.body.classList.remove('exploring');$('#spotSelect').value=id;state.checks.fill(0);state.hourly=[];state.outlook=[];$('.map-stage').classList.remove('card-hidden');$('#mapInfoToggle').textContent='Hide spot card';$('#mapInfoToggle').setAttribute('aria-expanded','true');mapCard(id,spots[id]._signal||'grey');map.flyTo([spots[id].lat,spots[id].lon],Math.max(map.getZoom(),13),{duration:.7});load()}
