const originalMapCard=mapCard;
mapCard=function(id,colour){originalMapCard(id,colour);let s=spots[id],badge=$('#evidenceBadge'),link=$('#evidenceLink'),unvalidatedRiver=s.type==='river'&&s.gaugeValidated!==true;badge.textContent=unvalidatedRiver?'◌ RESEARCH LEAD — GAUGE RANGE NOT VALIDATED':s.evidence?`✓ ${s.evidence.toUpperCase()}`:s.source?'◐ PUBLISHED SOURCE':'◌ RESEARCH LEAD';badge.className=unvalidatedRiver?'lead':s.evidence?'verified':s.source?'sourced':'lead';link.hidden=!s.source;if(s.source)link.href=s.source};
