// Profile v4 keeps ability separate for each discipline while retaining the compact two-mode UI.
openSetup=function(){let sup=$(`#setupForm input[name="skill_sup"][value="${state.skills?.sup||state.skills?.paddle||'beginner'}"]`);if(sup)sup.checked=true;['wing','windsurf','kite'].forEach(sport=>{let input=$(`#setupForm select[name="skill_${sport}"]`);if(input)input.value=state.skills?.[sport]||state.skills?.wind||'beginner'});$('#setupDialog').showModal()};
save=function(){let f=new FormData($('#setupForm'));state.skills={sup:f.get('skill_sup')||'beginner',wing:f.get('skill_wing')||'beginner',windsurf:f.get('skill_windsurf')||'beginner',kite:f.get('skill_kite')||'beginner'};state.skills.paddle=state.skills.sup;state.skills.wind=state.skills[state.sport]||state.skills.wing;state.skill=state.skills[state.sport]||'beginner';state.profile={leash:f.has('leash'),pfd:f.has('pfd'),comms:f.has('comms'),training:f.has('training'),solo:f.has('solo')};localStorage.setItem('shorewise-profile-v4',JSON.stringify({mode:state.mode,skills:state.skills,profile:state.profile,setupComplete:true}));render();toast('Saved separate SUP, wing, windsurf and kite levels')};
$('#profileButton').onclick=openSetup;$('#skillQuick').onclick=openSetup;
const renderPerDiscipline=render;
render=function(){state.sport=state.freeSport||state.sport||'sup';state.mode=state.sport==='sup'?'paddle':'wind';state.skills.paddle=state.skills.sup||'beginner';state.skills.wind=state.skills[state.sport]||'beginner';state.skill=state.skills[state.sport]||'beginner';renderPerDiscipline()};
$('#mapInfoToggle').onclick=()=>{let stage=$('.map-stage'),hidden=stage.classList.toggle('card-hidden'),button=$('#mapInfoToggle');button.textContent=hidden?'Show spot card':'Hide spot card';button.setAttribute('aria-expanded',String(!hidden));setTimeout(()=>map?.invalidateSize(),220)};

let smartAlternativeId=null;
function milesBetween(a,b){const r=3958.8,p=Math.PI/180,dLat=(b.lat-a.lat)*p,dLon=(b.lon-a.lon)*p,x=Math.sin(dLat/2)**2+Math.cos(a.lat*p)*Math.cos(b.lat*p)*Math.sin(dLon/2)**2;return 2*r*Math.asin(Math.sqrt(x))}
function exposureOf(s){if(Number.isFinite(s.exposure))return s.exposure;if(['lake','reservoir','river'].includes(s.type))return 0;if(['harbour','estuary'].includes(s.type))return 1;return 3}
const roadCache=new Map(),roadPending=new Set();
function smartAlternative(){let here=spots[state.spot],live=state.live,named=Object.entries(spots).find(([,s])=>s.name===here.alt)?.[0],hereExposure=exposureOf(here),local=new Map((here.localAlternatives?.[state.sport]||[]).map(x=>[x.id,x])),candidates=Object.entries(spots).filter(([id,s])=>id!==state.spot&&s.sports?.includes(state.sport)&&(s.evidence||s.source)&&!(s.type==='river'&&s.gaugeValidated!==true)).map(([id,s])=>{let distance=milesBetween(here,s),signal=s._signal||(live?signalFor(s,live):'grey'),localRule=local.get(id),distanceScore=distance<=15?65:distance<=30?42:distance<=50?15:-80,score=(signal==='green'?80:signal==='amber'?43:signal==='grey'?18:-25)+distanceScore;score+=s.evidence?13:6;if(id===named&&distance<=50)score+=12;if(localRule)score+=localRule.priority||20;if(live?.wave>=1.2&&exposureOf(s)<hereExposure)score+=(hereExposure-exposureOf(s))*18;if(state.skill==='beginner'&&exposureOf(s)>=3)score-=18;if(state.sport==='sup'&&['lake','reservoir'].includes(s.type)&&s.evidence)score+=12;if(state.sport==='sup'&&state.skill==='beginner'&&rnliPatrolState(s).active)score+=18;return{id,s,distance,signal,score,distanceScore,minutes:localRule?.minutes,note:localRule?.note}}).filter(x=>x.distance<=50&&(x.signal!=='red'||state.sport==='sup'&&['lake','reservoir'].includes(x.s.type))).sort((a,b)=>b.score-a.score);let winner=candidates[0]||null;if(winner)winner.shortlist=candidates.slice(0,5);return winner}
function alternativeReason(choice){let here=spots[state.spot],s=choice.s,bits=[];if(state.live){let currentRel=relation(state.live.dir,here.sea),nextRel=relation(state.live.dir,s.sea);if(['Offshore','Cross-offshore'].includes(currentRel)&&!['Offshore','Cross-offshore'].includes(nextRel))bits.push('safer wind angle');if(state.live.wave>=1.2&&exposureOf(s)<exposureOf(here))bits.push('more shelter from swell')}if(['lake','reservoir'].includes(s.type)&&['coast','harbour','estuary'].includes(here.type))bits.push('managed inland fallback');if(s.evidence)bits.push('documented local use');else bits.push('published location source');let journey=Number.isFinite(choice.minutes)?`about ${choice.minutes} min drive`:'road time not checked';return `${journey} · ${bits.slice(0,2).join(' · ')||choice.note||'different launch orientation'}`}
function roadKey(){return`${state.spot}|${state.sport}|${state.skill}|${state.selectedTime||'now'}`}
async function refineRoadAlternative(shortlist,key){if(!shortlist?.length||roadPending.has(key))return;roadPending.add(key);let here=spots[state.spot],coords=[[here.lon,here.lat],...shortlist.map(x=>[x.s.lon,x.s.lat])].map(x=>x.join(',')).join(';'),destinations=shortlist.map((_,i)=>i+1).join(';');try{let response=await fetch(`https://router.project-osrm.org/table/v1/driving/${coords}?sources=0&destinations=${destinations}`),json=await response.json(),durations=json?.durations?.[0]||[];let routed=shortlist.map((choice,i)=>({...choice,minutes:Number.isFinite(durations[i])?Math.round(durations[i]/60):choice.minutes})).filter(choice=>Number.isFinite(choice.minutes)&&choice.minutes<=60).map(choice=>({...choice,roadScore:choice.score-choice.distanceScore+(choice.minutes<=20?65:choice.minutes<=40?42:15)})).sort((a,b)=>b.roadScore-a.roadScore);roadCache.set(key,routed[0]||null)}catch(error){roadCache.set(key,null)}finally{roadPending.delete(key);if(key===roadKey())paintAlternative(roadCache.get(key),false,true)}}
function arrivalTip(){let s=spots[state.spot],d=state.live;if(d&&['Offshore','Cross-offshore'].includes(d.angle))return'Offshore wind? Don’t launch. Find a shore where it blows in or across.';if(s.type==='river')return'Fast flow, debris or rising water? Walk away.';if(s.type==='coast'&&d?.wave>=1)return'Watch three full sets. Find rips, rocks and a second exit.';if(state.sport==='sup')return'Stay within swimming distance. Blown away? Lie down and paddle diagonally to shore.';return'Before rigging, find your downwind exit.'}
function paintAlternative(choice,pending=false,routeChecked=false){let strong=$('.alt-score strong'),small=$('.alt-score small'),orb=$('.mini-orb');smartAlternativeId=choice?.id||null;$('#buddyTip').textContent=arrivalTip();if(!choice){$('#altName').textContent='No credible match within about an hour';$('#altMeta').textContent=routeChecked?'No road-time-qualified alternative found':'Check the map manually or change sport/profile';strong.textContent='No automatic redirect';small.textContent='A distant famous venue is not being presented as “nearby”';orb.textContent='—';return}$('#altName').textContent=choice.s.name;$('#altMeta').textContent=pending?'Checking actual road time…':alternativeReason(choice);strong.textContent=choice.signal==='green'?'Stronger local match for this profile':choice.signal==='red'?'Contained-water fallback — still not recommended in this wind':'Local option worth comparing';small.textContent=choice.s.intel||choice.s.access;orb.textContent=pending?'…':choice.signal==='green'?'✓':'!'}
function renderSmartAlternative(){let key=roadKey(),choice=smartAlternative();if(roadCache.has(key)){paintAlternative(roadCache.get(key),false,true);return}paintAlternative(choice,Boolean(choice),false);if(choice)refineRoadAlternative(choice.shortlist,key)}
const renderAlternatives=render;
render=function(){renderAlternatives();renderSmartAlternative()};
$('#routeButton').onclick=()=>{if(!smartAlternativeId)return toast('No evidence-backed nearby match for this sport and profile');chooseFromMap(smartAlternativeId);document.querySelector('.map-panel')?.scrollIntoView({behavior:'smooth',block:'start'})};
if(state.spot)render();

// V6 tester experience: one sport plus a local free area, with sport-specific readiness checks.
Object.assign(spots.tynemouth,{localAlternatives:{sup:[{id:'killingworth',minutes:18,priority:45,note:'restricted council lake; permission and qualification required'},{id:'qe2_lake',minutes:24,priority:42,note:'council-permitted inland water'},{id:'ladyburn',minutes:35,priority:38,note:'bookable sheltered-water centre and permit venue'}]}});

const FREE_RADIUS_MILES=35;
const readiness={
sup:{kit:[['right_leash','Correct leash for this water'],['buoyancy','Buoyancy aid for touring/open water'],['comms','Waterproof phone or VHF'],['buddy','I plan to paddle with someone']],ability:[['self_rescue','I can climb back on unaided'],['prone_return','I can lie down and paddle to shore'],['conditions','I recognise offshore wind and moving water']],awards:[['none','No formal award'],['lesson','Lesson with a qualified instructor'],['paddle_start','Paddle UK Start / Discover'],['paddle_explore','Paddle UK Explore or discipline award']]},
wing:{kit:[['board_leash','Board leash'],['wing_leash','Wing leash'],['impact','Impact vest / buoyancy aid'],['helmet','Helmet for foiling or harder conditions'],['buddy','I avoid sailing alone']],ability:[['self_rescue','I can depower and self-rescue'],['upwind','I can hold ground and return upwind'],['foil_control','I can fall clear and control the foil']],awards:[['none','No formal award'],['lesson','Lesson with a qualified instructor'],['learn_wing','RYA Learn / Improve Your Wingsurfing'],['first_flights','RYA Wingfoiling First Flights'],['sustained','RYA Wingfoiling Sustained Flights']]},
windsurf:{kit:[['exposure','Suitable wetsuit / exposure protection'],['harness','Harness with correctly set lines'],['helmet','Helmet for waves, foiling or harder conditions'],['comms','Waterproof means of calling for help'],['buddy','I avoid sailing alone in stronger wind']],ability:[['self_rescue','I can uphaul or self-rescue'],['harness_skill','I can use the harness confidently'],['planing','I can plane and use footstraps'],['return','I can return to my launch in changing wind']],awards:[['none','No formal award'],['lesson','Lesson with a qualified instructor'],['rya_start','RYA Start Windsurfing'],['rya_intermediate','RYA Intermediate (non-planing)'],['rya_planing','RYA Intermediate (planing)'],['rya_advanced','RYA Advanced / foiling course']]},
kite:{kit:[['helmet','Helmet'],['impact','Impact vest / flotation harness'],['release','Tested quick-release system'],['comms','Waterproof means of calling for help'],['buddy','Buddy launch / land and never alone']],ability:[['self_rescue','I can self-rescue and pack down'],['relaunch','I can relaunch in deep water'],['upwind','I can ride upwind and return'],['weather','I understand launch zones and squalls']],awards:[['none','No formal award'],['lesson','Lesson with a recognised kite school'],['independent','Signed off as an independent rider'],['advanced','Advanced coaching / rescue training']]}
};

function renderReadiness(sport=state.freeSport||'sup'){let config=readiness[sport]||readiness.sup,profile=state.profile||{},chosen=new Set(profile.readiness||[]);$('#sportKit').innerHTML=config.kit.map(([value,label])=>`<label><input type="checkbox" name="readiness" value="${value}" ${chosen.has(value)?'checked':''}><span>${label}</span></label>`).join('');$('#sportCapability').innerHTML=config.ability.map(([value,label])=>`<label><input type="checkbox" name="readiness" value="${value}" ${chosen.has(value)?'checked':''}><span>${label}</span></label>`).join('');$('#qualificationSelect').innerHTML=config.awards.map(([value,label])=>`<option value="${value}" ${profile.qualification===value?'selected':''}>${label}</option>`).join('')}
async function locateHome(query){let response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&countrycodes=gb,ie&q=${encodeURIComponent(query)}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Location lookup failed');let result=(await response.json())[0];if(!result)throw new Error('Area not found');return{label:result.display_name.split(',').slice(0,2).join(', '),lat:+result.lat,lon:+result.lon}}

function profileLabel(){return`${sports[state.freeSport]||'SUP'} · ${(state.skills[state.freeSport]||'beginner').replace(/^./,x=>x.toUpperCase())}`}
function inFreeArea(s){return !state.home||milesBetween(state.home,s)<=FREE_RADIUS_MILES}
function applyProfileMapFilter(){if(!map)return;Object.entries(spots).forEach(([id,s])=>{let visible=(s.hazardOnly||!s.sports||s.sports.includes(state.freeSport))&&inFreeArea(s),marker=markers[id];if(!marker)return;if(visible&&!map.hasLayer(marker))marker.addTo(map);else if(!visible&&map.hasLayer(marker))marker.removeFrom(map)});$$('#spotSelect option').forEach(option=>{if(!option.value)return;let s=spots[option.value],suitable=!s?.sports||s.sports.includes(state.freeSport);option.hidden=option.disabled=Boolean(s&&(!inFreeArea(s)||!suitable))})}
function updateProfileUI(){let button=$('#activeProfileButton');if(button){button.textContent=profileLabel();button.dataset.mode=state.freeSport==='sup'?'paddle':'wind'}$('#skillQuick').textContent=(state.skills[state.freeSport]||'beginner').replace(/^./,x=>x.toUpperCase());$('#profileInitials').textContent=(sports[state.freeSport]||'SUP').replace(/[^A-Za-z]/g,'').slice(0,2).toUpperCase();applyProfileMapFilter()}

openSetup=function(required=false){let sport=state.freeSport||'sup',sportInput=$(`#setupForm input[name="primary_sport"][value="${sport}"]`),level=state.skills[sport]||'beginner',levelInput=$(`#setupForm input[name="profile_skill"][value="${level}"]`),dialog=$('#setupDialog');if(sportInput)sportInput.checked=true;if(levelInput)levelInput.checked=true;$('#homeAreaInput').value=state.home?.query||'';renderReadiness(sport);dialog.classList.toggle('setup-required',required);dialog.dataset.required=required?'true':'false';if(!dialog.open)dialog.showModal()};
save=async function(){let form=$('#setupForm'),f=new FormData(form),sport=f.get('primary_sport')||'sup',skill=f.get('profile_skill')||'beginner',query=String(f.get('home_area')||'').trim(),dialog=$('#setupDialog');dialog.classList.add('setup-busy');$('#homeAreaError').hidden=true;try{let home=state.home?.query===query?state.home:await locateHome(query);home.query=query;state.home=home;state.freeSport=sport;state.sport=sport;state.mode=sport==='sup'?'paddle':'wind';state.skills[sport]=skill;state.skill=skill;state.profile={readiness:f.getAll('readiness'),qualification:f.get('qualification')||'none'};localStorage.setItem('shorewise-profile-v6',JSON.stringify({freeSport:sport,skills:state.skills,profile:state.profile,home:state.home,setupComplete:true}));hasSetup=true;dialog.dataset.required='false';dialog.classList.remove('setup-required');dialog.close();updateProfileUI();map?.setView([state.home.lat,state.home.lon],8);if(state.spot&&!inFreeArea(spots[state.spot])){state.spot='';state.live=null;$('#spotSelect').value=''}if(state.spot){render();updateMapSignals()}toast(`${profileLabel()} · local forecast around ${state.home.label}`)}catch(error){$('#homeAreaError').hidden=false}finally{dialog.classList.remove('setup-busy')}};
$('#profileButton').onclick=()=>openSetup(false);$('#skillQuick').onclick=()=>openSetup(false);$('#setupForm').onsubmit=event=>{event.preventDefault();save()};$$('#setupForm input[name="primary_sport"]').forEach(input=>input.onchange=()=>renderReadiness(input.value));$('#setupDialog').addEventListener('cancel',event=>{if($('#setupDialog').dataset.required==='true')event.preventDefault()});$('#upgradeButton').onclick=()=>toast('Premium preview: nationwide travel search, several sport profiles and charger planning — payments are not live yet.');

let fullMap=false;function setFullMap(on){fullMap=on;let stage=$('.map-stage'),button=$('#mapFullscreen');stage.classList.toggle('is-fullscreen',on);document.body.classList.toggle('map-open',on);button.textContent=on?'Close map':'Full screen';button.setAttribute('aria-label',on?'Close full-screen map':'Open full-screen map');setTimeout(()=>map?.invalidateSize(),120)}
$('#mapFullscreen').onclick=()=>setFullMap(!fullMap);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&fullMap)setFullMap(false)});

updateProfileUI();
if(!hasSetup)setTimeout(()=>openSetup(true),120);


